def kat_dla(kierunek):
    return {'polnoc': math.pi / 2, 'zachod': math.pi,
            'poludnie': -math.pi / 2, 'wschod': 0.0}[kierunek]

trasa = ['polnoc', 'zachod', 'poludnie', 'wschod']
katy = [kat_dla(kierunek) for kierunek in trasa]
oczekiwane = [math.pi / 2, math.pi, -math.pi / 2, 0.0]
kompas_gotowy = all(isinstance(kat, (int, float)) and math.isfinite(kat)
                    and math.isclose(kat, cel, abs_tol=0.001)
                    for kat, cel in zip(katy, oczekiwane))
print('✓ Kompas działa!' if kompas_gotowy else f'Uzupełnij kierunki: {katy}')
